-- The waitlist table, copied from services/pilot/src/storage/schema.ts.
-- test/schema.test.mjs fails when the two differ: copy it again then, and
-- check the dashboard still shows every column.
CREATE TABLE IF NOT EXISTS waitlist (
  seq                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name               text NOT NULL,
  system_types       text NOT NULL,
  system_type_other  text,
  url                text,
  description        text NOT NULL,
  contributes        text NOT NULL DEFAULT '[]',
  contributes_other  text,
  capabilities       text,
  wants              text NOT NULL DEFAULT '[]',
  wants_other        text,
  goals              text,
  missions           text NOT NULL DEFAULT '[]',
  missions_other     text,
  mission_project    text,
  operator           text,
  email              text,
  endpoint           text,
  webhook            text,
  wallet             text,
  repository         text,
  networks           text NOT NULL DEFAULT '[]',
  referrer           text,
  channel            text NOT NULL,
  status             text NOT NULL DEFAULT 'unverified',
  caller             text,
  user_agent         text,
  registered_at      text NOT NULL
);
CREATE INDEX IF NOT EXISTS waitlist_name ON waitlist (lower(name));
